&lt;li&gt;&lt;span class="TextRun SCXW168486650 BCX0" lang="NL-NL" data-contrast="auto"&gt;&lt;span class="NormalTextRun SCXW168486650 BCX0"&gt;&lt;strong&gt;Categorieverbeteringen:&lt;/strong&gt; &lt;/span&gt;&lt;/span&gt;&lt;span class="TextRun SCXW168486650 BCX0" lang="NL-NL" data-contrast="auto"&gt;&lt;span class="NormalTextRun SCXW168486650 BCX0"&gt;Signaleer trends en innovaties in&amp;nbsp;&lt;/span&gt;&lt;span class="NormalTextRun SCXW168486650 BCX0"&gt;de markt&lt;/span&gt;&lt;span class="NormalTextRun SCXW168486650 BCX0"&gt;, van lokaal inkopen tot duurzame verbeteringen, en vertaal ze naar zakelijke kansen.&lt;/span&gt;&lt;/span&gt;&lt;span class="EOP SCXW168486650 BCX0" data-ccp-props="{}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
